        print(' '.join(map(str, row)))

def transform_TENTATIVE(grid):
    """
    Rule: Find the main structure of 8s. Color each cell based on its position:
    - Top cap area (above first solid row) -> 2
    - Bottom wing area (below last solid row) -> 4
    - Inside solid region: center and left -> 1, right -> 3
    """
    if not grid or not any(grid[r][c] == 8 for r in range(len(grid)) for c in range(len(grid[0]))):
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find all 8 positions
    eight_positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8]

    if not eight_positions:
        return grid

    # Find bounding box
    min_r = min(p[0] for p in eight_positions)
    max_r = max(p[0] for p in eight_positions)
    min_c = min(p[1] for p in eight_positions)
    max_c = max(p[1] for p in eight_positions)

    # Find solid rows (rows where ALL rows in [min_c, max_c] are 8)
    solid_rows = []
    for r in range(min_r, max_r + 1):
        if all(grid[r][c] == 8 for c in range(min_c, max_c + 1)):
            solid_rows.append(r)

    if not solid_rows:
        return grid  # No solid rows, return as is

    result = [row[:] for row in grid]

    for r, c in eight_positions:
        if r < solid_rows[0]:
            # Top cap area
            result[r][c] = 2
        elif r > solid_rows[-1]:
            # Bottom wing area  
            result[r][c] = 4
        else:
            # Inside solid region
            # Check if this column is part of the solid region's columns
            if all(grid[r][x] == 8 for x in range(min_c, max_c + 1)):
                # This is a solid row - center/left -> 1, right -> 3
                center_col = (max_c + min_c) // 2
                if c <= center_col:
                    result[r][c] = 1
                else:
                    result[r][c] = 3
            else:
                # Non-solid row inside the row range
                # This is the "floating row" - becomes 1
                result[r][c] = 1

    return result


