def transform_simple(grid):
    """G0=2, G1=1, G2=4（最简规则）"""
    if not grid or not any(grid[r][c] == 8 for r in range(len(grid)) for c in range(len(grid[0]))):
        return grid

    rows = len(grid)
    num_cols = len(grid[0])

    row_data = {}
    for r in range(rows):
        cols_with_8 = sorted([c for c in range(num_cols) if grid[r][c] == 8])
        if cols_with_8:
            row_data[r] = cols_with_8

    sorted_rows = sorted(row_data.keys())
    pattern_groups = []
    for r in sorted_rows:
        new_pattern = tuple(row_data[r])
        if pattern_groups and pattern_groups[-1]['pattern'] == new_pattern:
            pattern_groups[-1]['rows'].append(r)
        else:
            pattern_groups.append({'pattern': new_pattern, 'rows': [r]})

    result = [row[:] for row in grid]

    for g_idx, g in enumerate(pattern_groups):
        for r in g['rows']:
            for c in g['pattern']:
                if g_idx == 0:
                    result[r][c] = 2
                elif g_idx == 1:
                    result[r][c] = 1
                else:
                    result[r][c] = 4

    return result

